package com.clavis.reader;
import android.content.Context;import android.util.AtomicFile;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import org.json.*;
final class ListenSession {
 boolean chapters;String key,title,text,note="";int position;final ArrayList<Integer> spines=new ArrayList<>();final ArrayList<Integer> starts=new ArrayList<>();final ArrayList<String> labels=new ArrayList<>();
 ListenSession(String key,String title,String text){this.key=key;this.title=title;this.text=text;}
 int chapterAt(int at){int index=0;for(int n=0;n<starts.size();n++)if(starts.get(n)<=at)index=n;return index;}
 int chapterEnd(int index){return index+1<starts.size()?starts.get(index+1):text.length();}
 String label(){return labels.isEmpty()?"Story":labels.get(chapterAt(position));}
 static File folder(Context c){File dir=new File(c.getFilesDir(),"listen");dir.mkdirs();return dir;}
 static File file(Context c,String key)throws Exception{byte[] hash=MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));StringBuilder name=new StringBuilder();for(byte b:hash)name.append(String.format(Locale.US,"%02x",b&255));return new File(folder(c),name+".json");}
 static ListenSession read(File file)throws Exception{try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>32*1024*1024)throw new IOException("Narration document is too large");out.write(buffer,0,n);}JSONObject j=new JSONObject(out.toString("UTF-8"));ListenSession s=new ListenSession(j.getString("key"),j.getString("title"),j.getString("text"));s.chapters=j.optBoolean("chapters");s.note=j.optString("note");s.position=Math.max(0,Math.min(s.text.length(),j.optInt("position")));JSONArray pages=j.optJSONArray("pages");if(pages!=null)for(int i=0;i<pages.length();i++){JSONObject p=pages.getJSONObject(i);s.starts.add(p.getInt("start"));s.labels.add(p.getString("label"));s.spines.add(p.optInt("spine",-1));}return s;}}
 void save(File file)throws Exception{JSONArray pages=new JSONArray();for(int n=0;n<starts.size();n++)pages.put(new JSONObject().put("start",starts.get(n)).put("label",labels.get(n)).put("spine",n<spines.size()?spines.get(n):-1));byte[] bytes=new JSONObject().put("key",key).put("title",title).put("text",text).put("chapters",chapters).put("note",note).put("position",position).put("pages",pages).toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>32*1024*1024)throw new IOException("Narration document is too large");AtomicFile atomic=new AtomicFile(file);FileOutputStream out=atomic.startWrite();try{out.write(bytes);atomic.finishWrite(out);}catch(Exception e){atomic.failWrite(out);throw e;}}
}
